function percentOf(value, total) {
  return (value / total) * 100;
}

module.exports = { percentOf };

const test = require('node:test');
const assert = require('node:assert');
const { percentOf } = require('./percent');

test('percentOf calculates percentage', () => {
  assert.strictEqual(percentOf(50, 100), 50);
  assert.strictEqual(percentOf(10, 200), 5);
  assert.strictEqual(percentOf(0, 100), 0);
});
